// Marka Koruma & Gizlilik: Bayilerin abone ve diğer bayilerin telefon son 4 hanesini görmesini engeller
export const maskPhoneLast4 = (phone: string | undefined | null, isMasked: boolean = true): string => {
  if (!phone) return '';
  if (!isMasked) return phone;
  const clean = phone.trim();
  const digitIndices: number[] = [];
  for (let i = 0; i < clean.length; i++) {
    if (/\d/.test(clean[i])) digitIndices.push(i);
  }
  if (digitIndices.length < 4) return clean;
  const last4 = new Set(digitIndices.slice(-4));
  let result = '';
  for (let i = 0; i < clean.length; i++) {
    result += last4.has(i) ? '*' : clean[i];
  }
  return result;
};

interface FastInputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  value: string;
  onValueChange: (val: string) => void;
  transform?: (val: string) => string;
}

const FastInput: React.FC<FastInputProps> = React.memo(({
  value,
  onValueChange,
  transform,
  className = '',
  dir = 'ltr',
  style,
  ...rest
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const isFocusedRef = useRef(false);

  useEffect(() => {
    if (inputRef.current && !isFocusedRef.current) {
      if (inputRef.current.value !== (value ?? '')) {
        inputRef.current.value = value ?? '';
      }
    }
  }, [value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let next = e.target.value;
    if (transform) {
      next = transform(next);
      e.target.value = next;
    }
    onValueChange(next);
  };

  return (
    <input
      ref={inputRef}
      defaultValue={value ?? ''}
      dir={dir}
      style={{ direction: 'ltr', textAlign: 'left', ...style }}
      onFocus={(e) => {
        isFocusedRef.current = true;
        rest.onFocus?.(e);
      }}
      onBlur={(e) => {
        isFocusedRef.current = false;
        if (inputRef.current && inputRef.current.value !== (value ?? '')) {
          onValueChange(inputRef.current.value);
        }
        rest.onBlur?.(e);
      }}
      onChange={handleChange}
      className={className}
      {...rest}
    />
  );
});
FastInput.displayName = 'FastInput';

// Türkçe karakterleri arama için normalize etme yardımcısı
export const normalizeTrSearch = (s: string) => {
  return (s || '')
    .toLocaleLowerCase('tr-TR')
    .replace(/ğ/g, 'g')
    .replace(/ü/g, 'u')
    .replace(/ş/g, 's')
    .replace(/ı/g, 'i')
    .replace(/ö/g, 'o')
    .replace(/ç/g, 'c')
    .trim();
};

export interface SearchableSelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  className?: string;
}

export interface SearchableSelectProps {
  value: string;
  onChange: (val: string) => void;
  options: (string | SearchableSelectOption)[];
  placeholder?: string;
  searchPlaceholder?: string;
  className?: string;
  disabled?: boolean;
  error?: boolean;
  id?: string;
}

export const SearchableSelect: React.FC<SearchableSelectProps> = ({
  value,
  onChange,
  options,
  placeholder = 'Seçiniz',
  searchPlaceholder = '🔍 Ara...',
  className = '',
  disabled = false,
  error = false,
  id
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const normalizedOptions: SearchableSelectOption[] = useMemo(() => {
    return options.map(opt => {
      if (typeof opt === 'string') {
        return { value: opt, label: opt };
      }
      return opt;
    });
  }, [options]);

  const selectedOption = useMemo(() => {
    return normalizedOptions.find(o => o.value === value);
  }, [normalizedOptions, value]);

  const filteredOptions = useMemo(() => {
    if (!searchTerm.trim()) return normalizedOptions;
    const query = normalizeTrSearch(searchTerm);
    return normalizedOptions.filter(opt => {
      const labelNorm = normalizeTrSearch(opt.label);
      const valNorm = normalizeTrSearch(opt.value);
      return labelNorm.includes(query) || valNorm.includes(query);
    });
  }, [normalizedOptions, searchTerm]);

  useEffect(() => {
    if (!isOpen) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        setSearchTerm('');
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 50);
    }
  }, [isOpen]);

  const displayLabel = selectedOption ? selectedOption.label : (value || placeholder);
  const isPlaceholderActive = !selectedOption && !value;

  return (
    <div ref={containerRef} className="relative w-full" id={id}>
      <button
        type="button"
        disabled={disabled}
        onClick={() => {
          if (!disabled) {
            setIsOpen(!isOpen);
            setSearchTerm('');
          }
        }}
        className={`w-full flex items-center justify-between text-left transition-all cursor-pointer ${
          className || 'bg-slate-900 border text-xs p-2 rounded'
        } ${
          error ? 'border-rose-500 bg-rose-500/5' : ''
        } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
      >
        <span className={`truncate mr-2 ${isPlaceholderActive ? 'text-slate-400 font-normal' : 'text-white font-medium'}`}>
          {displayLabel}
        </span>
        <div className="flex items-center gap-1 text-slate-400 shrink-0">
          {isOpen ? <ChevronUp className="w-3.5 h-3.5 text-sky-400" /> : <ChevronDown className="w-3.5 h-3.5" />}
        </div>
      </button>

      {isOpen && (
        <div className="absolute left-0 right-0 top-full mt-1.5 z-[9999] bg-slate-900 border-2 border-sky-500/80 rounded-2xl shadow-2xl p-2.5 space-y-2 backdrop-blur-xl">
          {/* Arama Input Kutusu */}
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-sky-400 absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            <input
              ref={searchInputRef}
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder={searchPlaceholder}
              className="w-full bg-slate-950 border border-slate-700 focus:border-sky-400 rounded-xl pl-8 pr-7 py-2 text-xs text-white placeholder:text-slate-500 outline-none font-medium"
              onKeyDown={(e) => {
                if (e.key === 'Escape') {
                  setIsOpen(false);
                  setSearchTerm('');
                }
              }}
            />
            {searchTerm && (
              <button
                type="button"
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white p-0.5 rounded cursor-pointer"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>

          {/* Filtrelenen Seçenekler Listesi */}
          <div className="max-h-56 overflow-y-auto space-y-1 pr-1 custom-scrollbar">
            {filteredOptions.length === 0 ? (
              <div className="p-3 text-center text-xs text-slate-400 font-medium">
                Sonuç bulunamadı ("{searchTerm}")
              </div>
            ) : (
              filteredOptions.map((opt) => {
                const isSelected = opt.value === value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    disabled={opt.disabled}
                    onClick={() => {
                      if (!opt.disabled) {
                        onChange(opt.value);
                        setIsOpen(false);
                        setSearchTerm('');
                      }
                    }}
                    className={`w-full text-left px-2.5 py-2 rounded-xl text-xs flex items-center justify-between transition-all cursor-pointer ${
                      opt.disabled ? 'opacity-40 cursor-not-allowed text-slate-500' :
                      isSelected
                        ? 'bg-sky-500/25 text-sky-300 font-bold border border-sky-500/50'
                        : 'text-slate-200 hover:bg-slate-800 hover:text-white'
                    } ${opt.className || ''}`}
                  >
                    <span className="truncate">{opt.label}</span>
                    {isSelected && <Check className="w-3.5 h-3.5 text-sky-400 shrink-0 ml-2" />}
                  </button>
                );
              })
            )}
          </div>
        </div>
      )}
    </div>
  );
};

