  // Arama kayıtlarının tekil olarak 1 ayını (30 gün) doldurduğunda arka planda otomatik temizlenmesi
  // Her kaydın kendi çağrı tarihine bakılır; 30 gününü dolduran tekil kayıt silinir, dolmayanlar kalır
  useEffect(() => {
    const autoCleanExpiredCallLogs = () => {
      const now = new Date();
      const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;
      setCallHistoryRecords(prev => {
        return prev.filter(record => {
          if (record.id?.startsWith('cl-')) return true; // Test aşamasındaki demo kayıtları koru
          try {
            const [datePart, timePart] = record.timestamp.split(' ');
            if (datePart) {
              const [d, m, y] = datePart.split('.').map(Number);
              const [hour, minute] = timePart ? timePart.split(':').map(Number) : [0, 0];
              if (d && m && y) {
                const recordDate = new Date(y, m - 1, d, hour || 0, minute || 0);
                // Çağrı anından itibaren tam 30 gün dolmamışsa sakla, 30 gün dolan silinir
                return (now.getTime() - recordDate.getTime()) < THIRTY_DAYS_MS;
              }
            }
          } catch {
            return true;
          }
          return true;
        });
      });
    };

    autoCleanExpiredCallLogs();
    const interval = setInterval(autoCleanExpiredCallLogs, 60 * 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  // Filter States
