  const filteredDealersDashboardList = useMemo(() => {
    return dealers.filter(d => {
      if (dealerDashboardProvince !== 'TÜMÜ' && d.province !== dealerDashboardProvince) return false;
      if (dealerDashboardDistrict !== 'TÜMÜ' && d.district !== dealerDashboardDistrict) return false;
      if ((dealerDashboardCategory === 'ILLER' || dealerDashboardCategory === 'IL') && !(d.canIssueDealership !== false || d.licenseTier === 'MASTER_1000')) return false;
      if (dealerDashboardCategory === 'ILCE' && !(d.canIssueDealership === false || d.licenseTier === 'STANDARD_500')) return false;
      if (dealerDashboardStatus !== 'TÜMÜ' && d.status !== dealerDashboardStatus) return false;
      if (dealerDashboardSearch.trim()) {
        const q = dealerDashboardSearch.toLowerCase().replace(/\s+/g, '');
        const name = (d.name || '').toLowerCase().replace(/\s+/g, '');
        const contact = (d.contactName || '').toLowerCase().replace(/\s+/g, '');
        const phone = (d.contactPhone || '').replace(/\s+/g, '');
        const prov = (d.province || '').toLowerCase();
        const dist = (d.district || '').toLowerCase();
        const code = (d.dealerCode || d.id || '').toLowerCase();
        return name.includes(q) || contact.includes(q) || phone.includes(q) || prov.includes(q) || dist.includes(q) || code.includes(q);
      }
      return true;
    });
  }, [dealers, dealerDashboardProvince, dealerDashboardDistrict, dealerDashboardCategory, dealerDashboardStatus, dealerDashboardSearch]);

