  const handleVoiceFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const result = typeof reader.result === 'string' ? reader.result : null;
      if (result) {
        setPendingVoiceUploadDataUrl(result);
        setPendingVoiceUploadName(file.name);
        setVoiceApplySuccessMessage(`"${file.name}" yüklendi. Dinle ile test edebilir veya Uygula ile tüm APK'lara geçerli kılabilirsiniz.`);
      }
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleApplyGlobalVoice = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!pendingVoiceUploadDataUrl) return;
    setIsApplyingVoiceUpload(true);
    try {
      let appliedUrl = pendingVoiceUploadDataUrl;
      try {
        const res = await fetch('/api/voice/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            audioDataUrl: pendingVoiceUploadDataUrl,
            fileName: pendingVoiceUploadName || 'sekreter_ornek_ses.mp3'
          })
        });
        if (res.ok) {
          const data = await res.json();
          if (data?.audioUrl) {
            appliedUrl = data.audioUrl;
          }
        }
      } catch {
        // Fallback to localStorage dataUrl if offline
      }

      geminiCallAssistant.setGlobalVoiceAudioUrl(appliedUrl, pendingVoiceUploadName);
      setAppliedVoiceFileName(pendingVoiceUploadName);
      setPendingVoiceUploadDataUrl(null);
      setVoiceApplySuccessMessage(`✅ "${pendingVoiceUploadName}" ses tonu tüm APK panellerinde (Yönetici, Bayiler ve Esnaf Aboneleri) aktif edildi!`);
    } finally {
      setIsApplyingVoiceUpload(false);
    }
  };

  const playVoiceSample = async (voiceKey: string) => {
    if (typeof window === 'undefined') return;

    if (isPlayingVoiceSample === voiceKey && activeAudioRef.current) {
      try {
        activeAudioRef.current.pause();
        activeAudioRef.current.currentTime = 0;
        activeAudioRef.current = null;
      } catch {}
      setIsPlayingVoiceSample(null);
      setVoiceSampleLivePreviewText('');
      return;
    }

    setIsPlayingVoiceSample(voiceKey);

    try {
      if (activeAudioRef.current) {
        activeAudioRef.current.pause();
        activeAudioRef.current.currentTime = 0;
        activeAudioRef.current = null;
      }
    } catch {}

    // Aktif APK'nın kayıtlı kişi adı, firma adı, rolü ve gelen/giden arama kurallarını birebir göster
    const personHonorific = getRegisteredPersonNameWithHonorific();
    const companyName = getRegisteredCompanyName();
    const roleSpoken = (() => {
      if (showCustomAssistantRoleInput && setupCustomAssistantRoleTitle.trim()) {
        return setupCustomAssistantRoleTitle.trim().replace(/\s+desin$/i, '').toLocaleLowerCase('tr-TR');
      }
      const found = setupAssistantRoleOptions.find((o) => o.id === setupAssistantRoleTitle);
      return found ? found.spokenText : 'asistanıyım';
    })();

    const incomingSample =
      setupUsageTarget === 'individual'
        ? `Ben ${getTrPossessive(personHonorific)} ${roleSpoken}, size nasıl yardımcı olabilirim?`
        : setupUsageTarget === 'company'
        ? `${getIncomingCompanyDisplayName()} hoş geldiniz, ben ${getTrPossessive(personHonorific)} ${roleSpoken}, size nasıl yardımcı olabilirim?`
        : `Ben ${companyName} firmasından ${getTrPossessive(personHonorific)} ${roleSpoken}, size nasıl yardımcı olabilirim?`;

    const outgoingSample =
      setupOutgoingHitapMode === 'NAME'
        ? `Merhaba, nasılsınız? Ben ${getTrPossessive(personHonorific)} ${roleSpoken}; ${personHonorific} sizinle görüşmek istiyor, hemen bağlıyorum.`
        : `Merhaba, nasılsınız? Ben ${companyName} firmasından ${getTrPossessive(personHonorific)} ${roleSpoken}; ${personHonorific} sizinle görüşmek istiyor, hemen bağlıyorum.`;

    const activeSkills: string[] = [];
    if (setupWarmTransferEnabled || setupSecretaryCallScreening) activeSkills.push('ön görüşmeli aktarma');
    if (setupAppointmentEnabled) activeSkills.push('randevu oluşturma');
    if (setupPriceQuotingEnabled) activeSkills.push('fiyat bilgisi verme');
    if (setupNegotiationEnabled) activeSkills.push(`yüzde ${setupDiscountLimit} indirim yetkisi`);
    if (setupOrderTakingEnabled) activeSkills.push('sipariş alma');

    const skillsSummary =
      activeSkills.length > 0
        ? `Aktif yetkilerim: ${activeSkills.join(', ')}.`
        : '';

    const fullRuleDrivenSample = `Gelen aramalarda: "${incomingSample}" diyerek karşılarım. Giden aramalarda ise: "${outgoingSample}" diyerek hattı bağlarım. ${skillsSummary}`.trim();
    setVoiceSampleLivePreviewText(fullRuleDrivenSample);

    try {
      const audioUrl = pendingVoiceUploadDataUrl || geminiCallAssistant.secretaryVoiceProfile.sampleAudioUrl;
      const audio = new Audio(audioUrl);
      activeAudioRef.current = audio;
      audio.onended = () => {
        if (activeAudioRef.current === audio) activeAudioRef.current = null;
        setIsPlayingVoiceSample(null);
      };
      audio.onerror = () => {
        if (activeAudioRef.current === audio) activeAudioRef.current = null;
        setIsPlayingVoiceSample(null);
      };
      await audio.play();
      return;
    } catch {
      setIsPlayingVoiceSample(null);
    }
  };
  const [setupPrice, setSetupPrice] = useState(150);
  const [setupGreetingPreset, setSetupGreetingPreset] = useState('Eczane');
  const [setupAppointmentEnabled, setSetupAppointmentEnabled] = useState(true);
  const [setupNegotiationEnabled, setSetupNegotiationEnabled] = useState(true);
  const [setupPriceQuotingEnabled, setSetupPriceQuotingEnabled] = useState(true);
  const [setupInfoProvisioningEnabled, setSetupInfoProvisioningEnabled] = useState(true);
  const [setupPromoMarketingEnabled, setSetupPromoMarketingEnabled] = useState(true);
  const [setupSupportTicketEnabled, setSetupSupportTicketEnabled] = useState(true);
  const [setupOrderTakingEnabled, setSetupOrderTakingEnabled] = useState(true);
