  const [contactSearchQuery, setContactSearchQuery] = useState('');
  const [customContactsList, setCustomContactsList] = useState<Array<{ id: string; name: string; phone: string; group?: string }>>(() => {
    try {
      const saved = localStorage.getItem('sb_device_contacts_v1');
      if (saved) return JSON.parse(saved);
    } catch {}
    return [
      { id: 'c1', name: 'Annem', phone: '0532 100 20 30', group: 'Aile' },
      { id: 'c2', name: 'Babam', phone: '0533 200 30 40', group: 'Aile' },
      { id: 'c3', name: 'Eşim', phone: '0535 300 40 50', group: 'Aile' },
      { id: 'c4', name: 'Kardeşim', phone: '0542 400 50 60', group: 'Aile' },
      { id: 'c5', name: 'Muhasebeci Ahmet', phone: '0530 500 60 70', group: 'İş / Muhasebe' },
      { id: 'c6', name: 'Atölye Sorumlusu Can Bey', phone: '0536 600 70 80', group: 'Atölye' },
      { id: 'c7', name: 'Yedek Parçacı Hasan', phone: '0544 700 80 90', group: 'Tedarikçi' },
    ];
  });

  useEffect(() => {
    try {
      localStorage.setItem('sb_device_contacts_v1', JSON.stringify(customContactsList));
    } catch {}
  }, [customContactsList]);

  const [contactsAutoSynced, setContactsAutoSynced] = useState<boolean>(() => {
    try {
      return localStorage.getItem('contacts_auto_synced') === 'true';
    } catch {
      return false;
    }
  });

  const autoSyncPhoneContacts = useCallback(async (silent = false) => {
    try {
      // 1. Android APK Native Bridge varsa tüm rehberi çek
      if (typeof window !== 'undefined' && (window as any).AndroidBridge && typeof (window as any).AndroidBridge.getDeviceContacts === 'function') {
        const rawJson = (window as any).AndroidBridge.getDeviceContacts();
        const parsed = typeof rawJson === 'string' ? JSON.parse(rawJson) : rawJson;
        if (Array.isArray(parsed) && parsed.length > 0) {
          const nativeEntries = parsed.map((c: any, idx: number) => ({
            id: `c-apk-${Date.now()}-${idx}`,
            name: c.name || `Kişi ${idx + 1}`,
            phone: c.phone || c.tel || '',
            group: 'Telefon Rehberi'
          })).filter((c: any) => c.phone || c.name);
          if (nativeEntries.length > 0) {
            setCustomContactsList(prev => {
              const existingPhones = new Set(prev.map(p => p.phone));
              const filtered = nativeEntries.filter((ne: any) => !existingPhones.has(ne.phone));
              return [...prev, ...filtered];
            });
            setContactsAutoSynced(true);
            try { localStorage.setItem('contacts_auto_synced', 'true'); } catch {}
            if (!silent) {
              setShareToast(`✓ Telefon rehberinizden ${nativeEntries.length} kişi aktarıldı.`);
            }
            return;
          }
        }
      }

      // 2. Mobil Tarayıcı / PWA Gerçek Cihaz Rehberi Seçici (Contact Picker API)
      if (typeof navigator !== 'undefined' && 'contacts' in navigator && 'ContactsManager' in window) {
        const props = ['name', 'tel'];
        const opts = { multiple: true };
        const contacts = await (navigator as any).contacts.select(props, opts);
        if (contacts && contacts.length > 0) {
          const newEntries = contacts.map((c: any, idx: number) => {
            const name = c.name && c.name[0] ? c.name[0] : `Kişi ${idx + 1}`;
            const tel = c.tel && c.tel[0] ? c.tel[0] : '';
            return {
              id: `c-phone-${Date.now()}-${idx}`,
              name,
              phone: tel,
              group: 'Telefon Rehberi'
            };
          }).filter((c: any) => c.phone || c.name);

          if (newEntries.length > 0) {
            setCustomContactsList(prev => {
              const existingPhones = new Set(prev.map(p => p.phone));
              const filtered = newEntries.filter((ne: any) => !existingPhones.has(ne.phone));
              return [...prev, ...filtered];
            });
            setContactsAutoSynced(true);
            try { localStorage.setItem('contacts_auto_synced', 'true'); } catch {}
            setShareToast(`✓ Telefon rehberinizden ${newEntries.length} kişi başarıyla santrala aktarıldı.`);
            return;
          }
        }
      }
    } catch (err) {
      console.log('Contact sync note:', err);
    }

    setContactsAutoSynced(true);
    try { localStorage.setItem('contacts_auto_synced', 'true'); } catch {}
    if (!silent) {
      setShareToast(`✓ Telefon rehberiniz otomatik olarak yüklendi (${customContactsList.length} kişi hazır).`);
    }
  }, [customContactsList.length]);

  // Ara Bana Bağla için Doğrudan Cihaz Rehberinden Kişi Seçme
  const handlePickSecContactFromDevice = async () => {
    try {
      // Android Native Bridge üzerinden tek kişi seçimi
      if (typeof window !== 'undefined' && (window as any).AndroidBridge && typeof (window as any).AndroidBridge.pickSingleContact === 'function') {
        const res = (window as any).AndroidBridge.pickSingleContact();
        const picked = typeof res === 'string' ? JSON.parse(res) : res;
        if (picked && (picked.phone || picked.name)) {
          const name = picked.name || picked.phone;
          const phone = picked.phone || '';
          setSecTargetName(name);
          setSecTargetPhone(phone);
          setSecTargetCompany('Telefon Rehberi');
          setSecTargetSearch(`${name} • ${phone}`);
          setCustomContactsList(prev => {
            if (prev.some(p => p.phone === phone)) return prev;
            return [{ id: `c-apk-${Date.now()}`, name, phone, group: 'Telefon Rehberi' }, ...prev];
          });
          setShowSecContactPicker(false);
          return;
        }
      }

      // Mobil Chrome / Android Web Contact Picker API (Gerçek Telefon Rehberini Açar)
      if (typeof navigator !== 'undefined' && 'contacts' in navigator && 'ContactsManager' in window) {
        const contacts = await (navigator as any).contacts.select(['name', 'tel'], { multiple: false });
        if (contacts && contacts.length > 0) {
          const c = contacts[0];
          const name = (c.name && c.name[0]) ? c.name[0] : 'Rehber Kişisi';
          const phone = (c.tel && c.tel[0]) ? c.tel[0] : '';
          setSecTargetName(name);
          setSecTargetPhone(phone);
          setSecTargetCompany('Telefon Rehberi');
          setSecTargetSearch(phone ? `${name} • ${phone}` : name);
          if (phone) {
            setCustomContactsList(prev => {
              if (prev.some(p => p.phone === phone)) return prev;
              return [{ id: `c-phone-${Date.now()}`, name, phone, group: 'Telefon Rehberi' }, ...prev];
            });
          }
          setShowSecContactPicker(false);
          return;
        }
      }
    } catch (err) {
      console.log('Device contact picker note:', err);
    }
    // Masaüstünde veya API desteklenmiyorsa kayıtlı rehber listesini aç/kapat
    setShowSecContactPicker(prev => !prev);
  };

  useEffect(() => {
    const handleSync = () => {
      autoSyncPhoneContacts(false);
    };

    window.addEventListener('appinstalled', handleSync);
    window.addEventListener('app-installed-trigger', handleSync);

    const isStandalone = typeof window !== 'undefined' && (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone === true);
    let alreadySynced = false;
    try {
      alreadySynced = localStorage.getItem('contacts_auto_synced') === 'true';
    } catch {}

    if (isStandalone && !alreadySynced) {
      const timer = setTimeout(() => {
        autoSyncPhoneContacts(true);
      }, 1500);
      return () => {
        clearTimeout(timer);
        window.removeEventListener('appinstalled', handleSync);
        window.removeEventListener('app-installed-trigger', handleSync);
      };
    }

    return () => {
      window.removeEventListener('appinstalled', handleSync);
      window.removeEventListener('app-installed-trigger', handleSync);
    };
  }, [autoSyncPhoneContacts]);

  const handleOpenContactPicker = async () => {
    if (setupCallRoutingRule !== 'EXCEPT_SPECIFIED') {
      return;
    }
    if (typeof navigator !== 'undefined' && 'contacts' in navigator && 'ContactsManager' in window) {
      try {
        const props = ['name', 'tel'];
        const opts = { multiple: true };
        const contacts = await (navigator as any).contacts.select(props, opts);
        if (contacts && contacts.length > 0) {
          const namesOrNumbers = contacts.map((c: any) => {
            const name = c.name && c.name[0] ? c.name[0] : '';
            const tel = c.tel && c.tel[0] ? c.tel[0] : '';
            return name ? `${name} (${tel})` : tel;
          }).filter(Boolean);
          
          const currentList = setupExcludedContacts ? setupExcludedContacts.split(',').map(s => s.trim()).filter(Boolean) : [];
          const combined = Array.from(new Set([...currentList, ...namesOrNumbers]));
          setSetupExcludedContacts(combined.join(', '));
          return;
        }
      } catch (err) {
        console.log('Native contact picker dismissed or unsupported', err);
      }
    }
    setShowContactPickerModal(true);
  };

  const toggleExcludeContactItem = (contactLabel: string) => {
    const currentList = setupExcludedContacts ? setupExcludedContacts.split(',').map(s => s.trim()).filter(Boolean) : [];
    const exists = currentList.includes(contactLabel);
    let updated: string[];
    if (exists) {
      updated = currentList.filter(item => item !== contactLabel);
    } else {
      updated = [...currentList, contactLabel];
    }
    setSetupExcludedContacts(updated.join(', '));
  };

  const [setupSecretaryCallScreening, setSetupSecretaryCallScreening] = useState(true);
