  const [setupIncomingCompanyType, setSetupIncomingCompanyType] = useState<'GENEL_MUDURLUK' | 'FIRMASINDAN' | 'CUSTOM'>('GENEL_MUDURLUK');
  const [setupIncomingCompanyCustom, setSetupIncomingCompanyCustom] = useState('');

