  const validateAndAddExtraPhone = () => {
    const trimmed = newExtraPhone.trim();
    if (!trimmed) {
      setNewExtraPhoneError('Lütfen bir telefon numarası giriniz.');
      return false;
    }

    // Clean non-digits
    const digits = trimmed.replace(/\D/g, '');
    
    // Turkish phone format check:
    // Mobile/landline without country code is either 10 digits (e.g. 5321234567) or 11 digits (e.g. 05321234567)
    // Landlines or 0850 are also 10 or 11 digits (e.g. 08503901234 / 8503901234, 02123456789 / 2123456789)
    // If it starts with country code, it can be 12 digits (e.g. 905321234567) or 13 digits (e.g. +905321234567)
    let normalized = digits;
    if (digits.length === 12 && digits.startsWith('90')) {
      normalized = digits.substring(2);
    }

    const isValid = (normalized.length === 10 && /^[234589]\d{9}$/.test(normalized)) ||
                    (normalized.length === 11 && /^0[234589]\d{9}$/.test(normalized));

    if (!isValid) {
      setNewExtraPhoneError('Geçersiz telefon formatı! Lütfen geçerli bir numara giriniz (Örn: 0532 123 4567)');
      return false;
    }

    setNewExtraPhoneError('');
    return true;
  };

