  const getRemainingLicenseDays = (roleKey: 'iller_bayi' | 'il_bayi' | 'ilce_bayi' | 'esnaf'): number => {
    if (roleKey === 'iller_bayi') return 365;
    if (roleKey === 'il_bayi' && dealerSantralOnlyStatus.il) return 30;
    if (roleKey === 'ilce_bayi' && dealerSantralOnlyStatus.ilce) return 30;

    const profile = setupProfilesRef.current[roleKey];
    const defaultInterval = (roleKey === 'il_bayi' || roleKey === 'ilce_bayi') ? 'yearly' : 'monthly';
    const interval = (setupOrigin === roleKey ? setupPaymentInterval : profile?.paymentInterval) || defaultInterval;
    const totalDays = interval === 'yearly' ? 365 : interval === '6months' ? 180 : 30;
    const startTime = profile?.licenseStartTime || Date.now();
    const elapsedDays = Math.floor(Math.max(0, Date.now() - startTime) / (1000 * 60 * 60 * 24));
    return Math.max(0, totalDays - elapsedDays);
  };

