  const validateStep1Fields = (): boolean => {
    const errors: { [key: string]: string } = {};
    if (!setupFullName.trim()) {
      errors.setupFullName = "Lütfen İsim Soyisim alanını doldurunuz.";
    }
    if (!setupCustomerName.trim()) {
      errors.setupCustomerName = "Lütfen İş Yeri Ünvanı alanını doldurunuz.";
    }
    if (!setupTcNo.trim()) {
      errors.setupTcNo = "Lütfen T.C. Kimlik Numaranızı giriniz.";
    } else if (setupTcNo.trim().length !== 11 || !/^\d{11}$/.test(setupTcNo.trim())) {
      errors.setupTcNo = "T.C. Kimlik Numarası 11 haneli rakam olmalıdır.";
    }
    if (!setupGender.trim()) {
      errors.setupGender = "Lütfen Cinsiyet seçiniz.";
    }
    if (!setupBirthYear.trim()) {
      errors.setupBirthYear = "Lütfen Doğum Yılı seçiniz.";
    }
    if (!setupBirthProvince.trim()) {
      errors.setupBirthProvince = "Lütfen Nüfusa Kayıtlı Olduğu İl seçiniz.";
    }
    if (!setupBirthDistrict.trim()) {
      errors.setupBirthDistrict = "Lütfen Nüfusa Kayıtlı Olduğu İlçe alanını doldurunuz.";
    }
    const cleanEmail = setupEmail.trim();
    if (!cleanEmail) {
      errors.setupEmail = "Lütfen Gmail / E-posta alanını doldurunuz.";
    } else if (!cleanEmail.includes('@') || !cleanEmail.includes('.')) {
      errors.setupEmail = "Lütfen geçerli bir e-posta formatı giriniz (Örn: ornek@gmail.com).";
    }
    if (!setupProfession.trim()) {
      errors.setupProfession = "Lütfen Meslek / Sektör alanını doldurunuz.";
    }
    const cleanPhone = setupCustomerPhone.replace(/\D/g, '');
    if (!cleanPhone || cleanPhone.length < 10) {
      errors.setupCustomerPhone = "Lütfen geçerli bir cep telefonu numarası giriniz (Örn: 0532 123 4567).";
    }

    if (Object.keys(errors).length > 0) {
      setSetupValidationErrors(errors);
      return false;
    }
    setSetupValidationErrors({});
    return true;
  };

  const validateStep2Fields = (): boolean => {
    const errors: { [key: string]: string } = {};
    if (!setupCallPickupMode) {
      errors.setupCallPickupMode = "Lütfen Çağrı Karşılama Modunu seçiniz.";
    }
    if (!setupCallRoutingRule) {
      errors.setupCallRoutingRule = "Lütfen Rehber & Arayan Filtresini seçiniz.";
    }
    if (!setupHoldMusic) {
      errors.setupHoldMusic = "Lütfen Bekletme & Aktarma Müziğini seçiniz.";
    }

    if (Object.keys(errors).length > 0) {
      setSetupValidationErrors(errors);
      return false;
    }
    setSetupValidationErrors({});
    return true;
  };

  const validateStep3Fields = (): boolean => {
    const errors: { [key: string]: string } = {};
    if (!setupVoice) {
      errors.setupVoice = "Lütfen Yapay Zeka Karşılama Sesini seçiniz.";
    }
    if (!setupGreetingTone) {
      errors.setupGreetingTone = "Lütfen Karşılama Hitap Tonunu seçiniz.";
    }
    const hasAnySkill = setupAppointmentEnabled || setupNegotiationEnabled || 
      setupPriceQuotingEnabled || setupInfoProvisioningEnabled || 
      setupPromoMarketingEnabled || setupSupportTicketEnabled || 
      setupOrderTakingEnabled || setupWarmTransferEnabled;
    
    if (!hasAnySkill) {
      errors.setupSkills = "Lütfen asistan için en az 1 yapay zeka yeteneğini aktif bırakınız.";
    }

    if (Object.keys(errors).length > 0) {
      setSetupValidationErrors(errors);
      return false;
    }
    setSetupValidationErrors({});
    return true;
  };

  // Controlled input helper to prevent cursor jumping to start / typing backwards (tersten yazılma sorununu çözer)
  const handleControlledInputChange = (
    e: React.ChangeEvent<HTMLInputElement>,
    setter: (val: string) => void,
    transform?: (val: string) => string,
    validationKey?: string
  ) => {
    const input = e.target;
    const rawVal = input.value;
    const finalVal = transform ? transform(rawVal) : rawVal;
    const prevPos = input.selectionStart ?? rawVal.length;

    let newPos = prevPos;
    if (transform && rawVal !== finalVal) {
      const charsBefore = transform(rawVal.slice(0, prevPos)).length;
      newPos = charsBefore;
    }

    setter(finalVal);

    if (validationKey && setupValidationErrors[validationKey]) {
      setSetupValidationErrors(prev => {
        if (!prev[validationKey]) return prev;
        const copy = { ...prev };
        delete copy[validationKey];
        return copy;
      });
    }

    requestAnimationFrame(() => {
      if (input && typeof input.setSelectionRange === 'function') {
        try {
          input.setSelectionRange(newPos, newPos);
        } catch (err) {}
      }
    });
  };

  const switchPortalProfile = (origin: 'admin' | 'iller_bayi' | 'il_bayi' | 'ilce_bayi' | 'esnaf' | string, targetId?: string) => {
    const cleanOrigin = String(origin || 'admin').replace('_portal', '');
    let newKey = cleanOrigin;
    if (cleanOrigin === 'admin') {
      newKey = 'admin';
    } else if (cleanOrigin === 'iller_bayi') {
      newKey = targetId ? 'dealer_' + targetId : 'iller_bayi';
    } else if (cleanOrigin === 'il_bayi') {
      newKey = targetId ? 'dealer_' + targetId : 'il_bayi';
    } else if (cleanOrigin === 'ilce_bayi') {
      newKey = targetId ? 'dealer_' + targetId : 'ilce_bayi';
    } else if (cleanOrigin === 'esnaf') {
      newKey = targetId ? 'subscriber_' + targetId : 'esnaf';
    }

    const existing = setupProfilesRef.current[newKey] || createInitialSetupProfile(newKey);
    setupProfilesRef.current[newKey] = existing;
    setSetupProfiles(prev => ({ ...prev, [newKey]: existing }));

    activeSetupProfileKeyRef.current = newKey;
    setActiveSetupProfileKey(newKey);
    setSetupOrigin(origin);
    applyProfileToForm(existing);
  };

  const returnToAuthorizedHome = (
    overrideRole?: 'admin' | 'iller_bayi' | 'il_bayi' | 'ilce_bayi' | 'esnaf' | null
  ) => {
    const role = overrideRole ?? authenticatedSessionRole ?? 'admin';
    if (role === 'iller_bayi') {
      setIsFromPanels(false);
      setActiveRole('DEALER');
      setSetupOrigin('iller_bayi');
      switchPortalProfile('iller_bayi');
      setAdminPanelsTab('iller_bayi');
      setCurrentApp('panels');
    } else if (role === 'il_bayi') {
      setIsFromPanels(false);
      setActiveRole('DEALER');
      setSetupOrigin('il_bayi');
      switchPortalProfile('il_bayi');
      setAdminPanelsTab('il_bayi');
      setCurrentApp('dealer_screen_portal');
    } else if (role === 'ilce_bayi') {
      setIsFromPanels(false);
      setActiveRole('DEALER');
      setSetupOrigin('ilce_bayi');
      switchPortalProfile('ilce_bayi');
      setAdminPanelsTab('ilce_bayi');
      setCurrentApp('district_dealer_portal');
    } else if (role === 'esnaf') {
      setIsFromPanels(false);
      setActiveRole('SUBSCRIBER');
      setSetupOrigin('esnaf');
      switchPortalProfile('esnaf');
      setAdminPanelsTab('esnaf');
      setCurrentApp('subscriber_portal');
    } else {
      setIsFromPanels(false);
      setActiveRole('ADMIN');
      setSetupOrigin('admin');
      switchPortalProfile('admin');
      setCurrentApp(null);
    }
  };

