  useEffect(() => {
    if (!authenticatedSessionRole) {
      if (!gsmAuthScreenState?.active) {
        setGsmAuthScreenState({
          active: true,
          step: 'PHONE',
          phone: '',
          enteredCode: '',
          generatedCode: '',
          errorMessage: '',
          targetRole: null,
          targetTitle: 'SantralBayi™ Yetkili Giriş'
        });
      }
      return;
    }
    if (authenticatedSessionRole !== 'admin' && currentApp === null) {
      returnToAuthorizedHome(authenticatedSessionRole);
    }
  }, [authenticatedSessionRole, currentApp, gsmAuthScreenState?.active]);

