                                              (hitapModalOpen === 'outgoing_company' && setupOutgoingCompanyType === 'GENEL_MUDURLUK') ||
                                              (hitapModalOpen === 'outgoing_hybrid' && setupOutgoingHybridType === 'GENEL_MUDURLUK')
