                                                if (hitapModalOpen === 'outgoing_company') setSetupOutgoingCompanyType(setupOutgoingCompanyType === 'CUSTOM' ? 'GENEL_MUDURLUK' : 'CUSTOM');
                                                if (hitapModalOpen === 'outgoing_hybrid') setSetupOutgoingHybridType(setupOutgoingHybridType === 'CUSTOM' ? 'GENEL_MUDURLUK' : 'CUSTOM');
