                                                (hitapModalOpen === 'incoming_company' && setupIncomingCompanyType === 'CUSTOM') ||
                                                (hitapModalOpen === 'incoming_hybrid' && setupIncomingHybridType === 'CUSTOM') ||
                                                (hitapModalOpen === 'outgoing_company' && setupOutgoingCompanyType === 'CUSTOM') ||
                                                (hitapModalOpen === 'outgoing_hybrid' && setupOutgoingHybridType === 'CUSTOM')
                                                  ? 'bg-emerald-500 shadow-md shadow-emerald-500/20'
                                                  : 'bg-slate-700'
