                            const entityIban = (selectedEntity as any).iban || (isIl ? 'TR32 0006 1005 1234 5678 9012 34' : isIlce ? 'TR14 0001 0009 8765 4321 0987 65' : 'TR56 0006 2000 1122 3344 5566 77');

                            const apkDistributed = (selectedEntity as any).apkDistributed || (isIl ? 120 + connectedSubDealersCount * 25 : isIlce ? 35 + connectedSubscribersCount * 3 : 1);
                            const apkConverted = (selectedEntity as any).apkConverted || (isIl ? (connectedSubscribersCount > 0 ? connectedSubscribersCount : 38) : isIlce ? connectedSubscribersCount : 1);
                            const apkDropped = (selectedEntity as any).apkDropped || (isIl ? 4 : isIlce ? 2 : ((selectedEntity as any).apkStatus === 'DROPPED' ? 1 : 0));
                            const apkReturned = (selectedEntity as any).apkReturned || (isIl ? 2 : isIlce ? 1 : ((selectedEntity as any).apkStatus === 'RETURNED' ? 1 : 0));
                            const apkVersion = (selectedEntity as any).apkVersion || 'v1.1';
                            const conversionRate = apkDistributed > 0 ? Math.round((apkConverted / apkDistributed) * 100) : 0;

                            const referredBy = (selectedEntity as any).referredBySubscriberName || 'Doğrudan İlçe Bayisi Saha Dağıtımı';
