                          receiptFileName: inc.receiptFileName || null,
                          receiptTimestamp: inc.receiptTimestamp || null,
                          receiptExpired: inc.receiptExpired || false,
                          receiptNo: inc.receiptNo || null,
                          handwrittenNote: inc.handwrittenNote || null,
